/* Replay dhcpc_parseoptions() over the raw frame, because 0915-1 showed
 * op, xid and chaddr all matching: dhcpc_parsemsg() passes its three
 * gates and returns whatever dhcpc_parseoptions() makes of the options,
 * which is 0 for anything it cannot parse -- and a 0 return is discarded
 * without a log line at any debug level, so no amount of DEBUG_NET
 * reaches it.
 *
 * Reproducing the walk here rather than printing a few option bytes,
 * because the failure could be an option whose length byte makes the
 * walk step over the message type: the first bytes would look fine and
 * cost another flash cycle.  Same algorithm as dhcpc.c:337-438, over
 * frame bytes instead of the received copy.
 *
 * msgtype=2 means the frame carries a well-formed OFFER and the loss is
 * downstream of it, in what recv() handed dhcpc.  parseoptions is given
 * len = buflen - (offsetof(options) + 4), so a short recv() shrinks the
 * region it walks; that is worth suspecting here specifically because
 * IOB_BUFSIZE is 196 and this 352-byte frame is the first one that has
 * to span an IOB chain.  Every frame ping proved -- ARP 42, ICMP 98 --
 * fit in a single IOB.
 *
 * DHCP options start at DHCP offset 236, i.e. frame offset 278 with the
 * 14-byte Ethernet header and a 20-byte IPv4 header, and the walk itself
 * begins after the 4-byte magic cookie at frame 282. */

{
  unsigned int end = (unsigned int)p->len;
  unsigned int i = 282;
  unsigned int msgtype = 0;
  unsigned int seen = 0;

  while (i < end && seen < 32u)
    {
      seen++;

      if (b[i] == 255)       /* DHCP_OPTION_END */
        {
          break;
        }

      if (b[i] == 53 && i + 2 < end)   /* DHCP_OPTION_MSG_TYPE */
        {
          msgtype = b[i + 2];
        }

      if (i + 1 >= end)
        {
          break;
        }

      i += b[i + 1] + 2;
    }

  syslog(LOG_WARNING,
         "[BK7258-WIFI] dhcp#%u udplen=%u cookie=%02x%02x%02x%02x "
         "msgtype=%u opts_walked=%u stop=%u/%u\n",
         dhcp_probe_count,
         (unsigned)((b[38] << 8) | b[39]),
         b[278], b[279], b[280], b[281],
         msgtype, seen, i, end);
}

