static int bk7258_wifi_isr_trampoline(int irq, void *context, void *arg)
{
  struct bk7258_wifi_isr_slot *slot = arg;
  (void)irq;
  (void)context;
  if (slot != NULL && slot->callback != NULL)
    {
      unsigned idx = (unsigned)(slot - g_wifi_isr);

      /* TEMPORARY preemption-lock balance probe (2026-09-15) -- remove once the
       * sched_unlock assert is attributed.
       *
       * Two asserts have fired from sched_unlock()'s
       * DEBUGASSERT(lockcount > 0), expanded at its call site so it reports
       * whichever caller ran first: drivers/serial/serial.c:2064 under ping and
       * ifconfig output, and sched/task/task_exithook.c:479 while renew exited.
       * Both had xPSR bit pattern 11, SVCall, i.e. the assert landed inside a
       * context switch.
       *
       * The question this probe answers is whose fault that is, and it is the
       * one thing measurable entirely from our side.  this_task() is
       * g_readytorun.head in a non-SMP build (sched.h:257), so a vendor callback
       * that takes a preemption lock and returns without releasing it -- or
       * releases one it never took -- corrupts the count of whatever task is at
       * the head.  If the count is balanced across every vendor ISR callback,
       * our adapter is clean and the imbalance comes from elsewhere.
       *
       * sched_lockcount() is a plain read of that field, safe to call here.
       * Bounded to 12 records so it cannot flood the port it shares with the
       * console. */

      int lock_before = sched_lockcount();

      bk7258_wifi_isr_count[idx]++;
      slot->callback(slot->arg);

      {
        int lock_after = sched_lockcount();
        static unsigned int lockprobe_count;

        if (lock_before != lock_after && lockprobe_count < 12u)
          {
            lockprobe_count++;
            syslog(LOG_WARNING,
                   "[BK7258-WIFI] lockbal#%u src=%u before=%d after=%d\n",
                   lockprobe_count, idx, lock_before, lock_after);
          }
      }
    }
  return OK;
}

